from h import *
R(9692965,"البيكان في القلاية الهوائية [بنكهتين]",
"بيكان مقرمش يسبب الإدمان في القلاية الهوائية بنكهتين لذيذتين!",
"6 حصص","حصة واحدة",
["¼ كوب سكر بني أو سكر جوز الهند غير المكرر","½ ملعقة صغيرة قرفة","2 ملعقة كبيرة ماء","1 ملعقة صغيرة خلاصة فانيليا طبيعية","1.5 كوب نصفا حبات بيكان","1 ملعقة كبيرة شراب القيقب أو دبس التمر أو أي محلٍّ سائل من اختيارك","1 ملعقة كبيرة صلصة صويا أو تاماري للخالي من الغلوتين","¼ ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","⅛ ملعقة صغيرة فلفل كايين","1.5 كوب نصفا حبات بيكان"],
["حدّد النكهة التي ستحضّرها، الحلوة أم المتبّلة. ثم اخلط المكونات الأربعة الأولى الخاصة بتلك النكهة في وعاء صغير وضعه جانبًا. ضع البيكان في وعاء آخر واسكب الخليط فوقه. اخلط جيدًا للتأكد من تغليف كل نصف حبة بيكان.","بطّن صينية خبز صغيرة بورق الزبدة وضعها جانبًا. ثم اغرف البيكان المغلف إلى سلة القلاية الهوائية بالملعقة ولا تسكبه دفعة واحدة. اطهُه في القلاية الهوائية على 350 درجة فهرنهايت (175° مئوية) لمدة 3-5 دقائق، مع التقليب أو رج السلة عند منتصف الوقت. راقبه بعناية لمنع الاحتراق. فهو ينضج بسرعة.","انقل البيكان إلى صينيتك المبطنة بورق الزبدة في طبقة واحدة ليبرد. حاول بكل جهدك ألا تلتهمه وهو دافئ، لأنه سيتصلب ويصبح مقرمشًا عند التبريد، وهذا هو الوقت الذي يكون طعمه فيه أفضل. بالهناء والشفاء! ;)"],
["وزّع البيكان في طبقة واحدة بعد الطهي في القلاية الهوائية إلى أن يبرد. حاول بكل جهدك ألا تأكله وهو دافئ (رغم أنه لذيذ وهو دافئ أيضًا). ستسمح فترة التبريد هذه له بالتصلب وستمنعه من الالتصاق ببعضه. يبرد بسرعة وسيكون جاهزًا للأكل في حوالي 10-15 دقيقة. يُحفظ المتبقي في درجة حرارة الغرفة في وعاء مغلق أو برطمان لمدة 1-2 أسبوع. المعلومات الغذائية أعلاه تمثل حصة واحدة من البيكان الحلو المكرمل. أما البيكان المتبّل فهو أخف قليلًا بـ 182 سعرة حرارية و3 غرامات من السكر للحصة الواحدة."],
{"Air Fryer Candied Pecans":"بيكان مكرمل في القلاية الهوائية","Air Fryer Spiced Pecans":"بيكان متبّل في القلاية الهوائية"})
R(9693255,"وافل الشوكولاتة النباتي",
"حضّر وافل الشوكولاتة النباتي هذا بخمسة مكونات، غني وهش ولذيذ تمامًا.",
"6 وافل","حصة واحدة",
["120 غرامًا دقيق القمح الكامل حوالي 1 كوب","3 ملاعق كبيرة مسحوق الكاكاو","2 ملعقة صغيرة بيكنج باودر","1 كوب حليب صويا أو أي حليب نباتي من اختيارك","1 ملعقة كبيرة خلاصة فانيليا طبيعية"],
["سخّن مكواة الوافل على حرارة متوسطة إلى عالية، أو وفق تعليمات الشركة المصنّعة.","ضع الدقيق ومسحوق الكاكاو والبيكنج باودر في وعاء خلط كبير واخفقها حتى تمتزج. ثم أضف الحليب والفانيليا وحرّك حتى لا تبقى أي بقع دقيق، دون الإفراط في الخلط.","اغرف العجين على مكواة الوافل المسخنة واطهه وفق تعليمات الشركة المصنّعة، حوالي 4-6 دقائق، أو حتى تصل إلى درجة النضج المطلوبة."],
["زِن الدقيق للحصول على أفضل النتائج. فإذا غرفتَه من الكيس فقد تضع كمية زائدة وتحتاج إلى سائل أكثر لتصل بالعجين إلى القوام المناسب.","زِن الدقيق والمسحوق للحصول على أفضل النتائج. فإذا غرفتَهما من الكيس فقد تضع كمية زائدة وتحتاج إلى سائل أكثر لتصل بالعجين إلى القوام المناسب.","إذا لم يكن لديك ميزان مطبخ، فاغرف الدقيق بالملعقة إلى كوب القياس واستخدم سكينًا لإزالة الزائد.","تأكد من أن مكواة الوافل ساخنة قبل وضع عجين الوافل فيها، لمنع الالتصاق.","لا ترفع الغطاء مبكرًا جدًا وإلا فقد ينكسر الوافل. بل ارفع الغطاء ببطء وحذر للتحقق من الالتصاق.","الدفعات التالية من الوافل تنضج أسرع قليلًا من الدفعة الأولى، لذا راقبها عن كثب.","يُحفظ الوافل المتبقي في الثلاجة لمدة 3-4 أيام أو في الفريزر لمدة تصل إلى 3 أشهر."])
R(9702522,"وافل حليب جوز الهند [بدون زيت]",
"وافل حليب جوز الهند مقرمش من الخارج، لكنه طري وهش من الداخل.",
"10 وافل","حصة واحدة",
["270 غرامًا دقيق القمح الكامل حوالي 2 كوب يُغرف بالملعقة ويُسوّى","2 ملعقة صغيرة بيكنج باودر","400 مل حليب جوز هند غير محلّى من Thai Kitchen حوالي علبة 13.5 أونصة","⅓ كوب موز مهروس حوالي حبة موز صغيرة جدًا أو نصف حبة كبيرة","1 ملعقة صغيرة خلاصة فانيليا طبيعية","2-4 ملاعق كبيرة ماء عند الحاجة","مربى التوت الأزرق بالشيا","فاكهة طازجة","شراب القيقب"],
["سخّن مكواة الوافل على حرارة متوسطة إلى عالية.","في وعاء خلط كبير، اخفق الدقيق والبيكنج باودر معًا. ثم أضف حليب جوز الهند والموز والفانيليا واخلط حتى تمتزج فقط، ولا تبقى أي بقع دقيق، لكن دون الإفراط في الخلط. بعض الكتل لا بأس بها إطلاقًا. ملاحظة: إذا بدا العجين سميكًا جدًا (يجب أن يكون قابلًا للصب كعجين البانكيك)، فأضف الماء الاختياري وقلّب كل شيء مرة أخرى بسرعة.","اطهُ الوافل وفق تعليمات الشركة المصنّعة، حوالي 5-6 دقائق لكل دفعة. اطهُه لفترة أطول للحصول على وافل أكثر قرمشة، ولفترة أقل للحصول على وافل أطرى.","قدّمه مع مربى التوت الأزرق بالشيا أو شراب القيقب أو الفاكهة الطازجة."],
["استخدم حليب جوز الهند المعلب (كامل الدسم أو الخفيف) لكن لا تستبدله بحليب نباتي آخر. فمحتوى الدهون ضروري للحصول على وافل أكثر قرمشة، خاصةً أن هذه الوصفة لا تتضمن زيتًا أو زبدة. زِن الدقيق للحصول على أفضل النتائج. فإذا غرفت الدقيق من الكيس، فمن المرجح أن تضع كمية زائدة وستحتاج إلى سائل أكثر لتصل بالعجين إلى القوام المناسب تمامًا. وإذا لم يكن لديك ميزان مطبخ، فاغرف الدقيق بالملعقة إلى كوب القياس واستخدم سكينًا لإزالة الزائد. استخدم موزًا ناضجًا جدًا عليه بقع بنية للحصول على حلاوة طبيعية وأفضل نكهة. تأكد من أن مكواة الوافل ساخنة قبل وضع عجين الوافل فيها، لمنع الالتصاق. لا ترفع الغطاء مبكرًا جدًا وإلا فقد ينكسر الوافل. انتظر على الأقل الحد الأدنى من الدقائق الذي تحدده تعليمات الشركة المصنّعة قبل التحقق من درجة النضج. الدفعات التالية من الوافل تنضج أسرع قليلًا من الدفعة الأولى لذا راقبها عن كثب."],
{"Optional Toppings":"إضافات اختيارية"})
R(9702792,"أرز بسمتي بني بجوز الهند في الإنستانت بوت",
"أرز جوز الهند في الإنستانت بوت طبق جانبي رائع مع أي وجبة. يُحضّر بسرعة، بمكونات صحية ونكهة قوية!",
"6 حصص","حصة واحدة",
["2 كوب أرز بسمتي بني","1 علبة حليب جوز هند خفيف سعة 400 مل","1 كوب ماء","½ ملعقة صغيرة ملح البحر"],
["ضع الأرز في مصفاة واشطفه جيدًا بالماء البارد.","ضع جميع المكونات في الإنستانت بوت وقلّبها جيدًا. تأكد من أن الأرز مغطى بالسوائل ليتم نضجه بالتساوي. ثم أغلق الغطاء وتأكد من أن صمام التفريغ في وضع الإغلاق. اضبطه على الضغط العالي لمدة 22 دقيقة. (سيستغرق بناء الضغط حوالي 10 دقائق قبل بدء العد التنازلي.)","اترك الضغط ينفّس تلقائيًا لمدة 10 دقائق، ثم فرّغ أي ضغط متبقٍّ بصمام التفريغ.","قلّبه بالشوكة وبالهناء والشفاء!"],
["اشطف الأرز جيدًا قبل الطهي لإزالة النشا ومنع الأرز من الالتصاق والتكتل. رجّ علبة حليب جوز الهند قبل فتحها وسكبها في القدر. فالماء ومحتوى جوز الهند ينفصلان عند تركها، لذا رجّها جيدًا. أحب استخدام حليب جوز الهند الخفيف لإبقاء محتوى الدهون والسعرات الحرارية أقل، لكن إذا أردت نكهة جوز هند أقوى وغنى أكبر، فاختر النسخة كاملة الدسم. تأكد من تقليب الأرز جيدًا جدًا بعد إضافة السوائل إلى الإنستانت بوت. فأنت لا تريد أي حبات أرز فوق مستوى السوائل وإلا فلن تنضج تلك القطع جيدًا. للحصول على نكهة إضافية، قلّب ⅓ كوب من البصل المفروم ناعمًا قبل إضافة بقية المكونات والطهي بالضغط. وبعد الطهي، يمكنك أيضًا عصر بعض عصير الليمون أو الليمون الأخضر الطازج فوق الأرز والخلط جيدًا قبل التقديم."])
R(9706219,"نودلز الكوسا بنكهة البوريتو",
"استمتع بلمسة صحية على الطبق الكلاسيكي مع نودلز الكوسا بنكهة البوريتو!",
"4 حصص","حصة واحدة",
["3 حبات كوسا متوسطة","1 كوب طماطم كرزية (أو عنبية) مقطعة إلى نصفين","½ كوب حبات ذرة","علبة فاصوليا سوداء سعة 15 أونصة مصفاة + مغسولة","2 ملعقة كبيرة عصير ليمون أخضر حوالي ليمونة خضراء كبيرة واحدة","1 ملعقة صغيرة بابريكا مدخنة","1 ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة مسحوق الثوم","ملح + فلفل حسب الرغبة","كزبرة خضراء طازجة","كريما فريسكا","شرائح أفوكادو","شرائح ليمون أخضر"],
["ابدأ بتحويل الكوسا إلى نودلز بالقطّاعة الحلزونية إذا كنت لا تستخدم نودلز الكوسا الجاهزة من المتجر. ضع نودلز الكوسا في مصفاة كبيرة داخل وعاء كبير أو حوض المطبخ ورشّ عليها الملح بسخاء. سيؤدي ذلك إلى تذبيل الكوسا وتحسين نكهتها. اتركها جانبًا لمدة 10-15 دقيقة أثناء تحضير بقية المكونات.","ثم حضّر أي إضافات و/أو صلصات تريد استخدامها.","بعد ذلك، سخّن الفاصوليا مع عصير الليمون الأخضر والتوابل لبضع دقائق لتمتص النكهات ثم أطفئ النار.","يمكنك اختياريًا تسخين نودلز الكوسا، لكن لا حاجة إلى طهيها.","قدّم نودلز الكوسا بنكهة البوريتو في أوعية غير عميقة وضع فوقها الفاصوليا الساخنة وبقية الإضافات. بالهناء والشفاء."],
["حضّر الإضافات وحوّل الكوسا إلى نودلز بالقطّاعة الحلزونية قبل تسخين الفاصوليا.","لتسهيل التقطيع الحلزوني، استخدم كوسا رفيعة وطويلة ومستقيمة. أو يمكنك شراء نودلز كوسا جاهزة معبأة من متجر البقالة لتوفير الوقت.","لا تفرط في طهي نودلز الكوسا. يمكنك تقديمها نيئة وباردة، أو دافئة قليلًا فقط. فتسخينها لفترة طويلة جدًا سيجعلها مائية وطرية أكثر من اللازم."],
{"Optional Toppings":"إضافات اختيارية"})
R(9708016,"خبز الكوسا بالشوكولاتة النباتي [بدون زيت أو سكر]",
"طعم خبز الكوسا بالشوكولاتة النباتي هذا أقرب إلى الكعكة، ولكن دون كل ذلك السكر! يحلّي التمر هذه الحلوى اللذيذة ويخفي أي أثر للخضار!",
"12 شريحة (قالب رغيف واحد مقاس 5\"×9\")","شريحة واحدة",
["190 غرامًا دقيق الشوفان، حوالي 2 كوب خالٍ من الغلوتين إن رغبت","⅓ كوب مسحوق كاكاو نيء غير محلّى","2.5 ملعقة صغيرة بيكنج باودر","¼ ملعقة صغيرة ملح البحر","1 كوب تمر منزوع النوى مكبوس","¼ كوب ماء","2 ملعقة صغيرة خلاصة فانيليا طبيعية","2 كوب كوسا مبشورة، مكبوسة برفق حوالي حبة كوسا متوسطة واحدة (اعصر الرطوبة الزائدة فوق حوض المطبخ)","1¼ كوب حليب كاجو غير محلّى أو أي حليب نباتي من اختيارك","⅓ كوب رقائق شوكولاتة داكنة بالإضافة إلى المزيد للرش على الوجه إن أحببت"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (176° مئوية) وبطّن قالب رغيف مقاس 5\"×9\" بورق الزبدة.","اخفق جميع المكونات الجافة في وعاء كبير وضعه جانبًا.","ضع التمر والماء في محضّر الطعام وشغّله على نبضات متقطعة حتى يتكون معجون، مع كشط الجوانب عند الحاجة. انقل معجون التمر إلى وعاء المكونات الجافة، مع جميع المكونات المتبقية بما في ذلك رقائق الشوكولاتة إن استخدمتها. اخلط حتى لا تبقى أي بقع دقيق.","اسكب العجين في قالب الرغيف المجهز. رشّ مزيدًا من رقائق الشوكولاتة إن أحببت، واضغط عليها برفق.","اخبزه لمدة 50-55 دقيقة، أو حتى يخرج عود الأسنان نظيفًا تقريبًا. ثم أخرجه من الفرن واتركه يبرد 10 دقائق على الأقل قبل نقله بحذر إلى رف تبريد ليبرد تمامًا قبل التقطيع. بالهناء والشفاء!"],
["قِس مكوناتك وحضّرها قبل أن تبدأ. فهذا سيضمن ألا تنسى شيئًا، ولن تشعر بالعجلة في تحضير المكونات بين الخطوات.","زِن الدقيق للحصول على أدق النتائج. فغرف الدقيق من الكيس غالبًا ما يؤدي إلى استخدام كمية زائدة منه، وسيغير قوام الرغيف. وإذا كان لا بد من استخدام أكواب القياس، فاغرف الدقيق بالملعقة إلى الكوب، وأزل الزائد بظهر السكين.","اعصر الكوسا المبشورة لإخراج رطوبتها الزائدة في وعاء، أو فوق حوض المطبخ، قبل خلطها في عجين الكعكة.","استخدم ورق الزبدة في قالب الرغيف. فهذا لا يسهّل نقل الرغيف بعد الخبز فحسب، بل يعني أيضًا أنه يمكنك تجنب دهن القالب.","برّد خبز الكوسا بالشوكولاتة النباتي تمامًا إلى درجة حرارة الغرفة قبل التقطيع. فوقت التبريد يساعد الرغيف على التماسك ويسهّل التقطيع.","بلّل سكينك بين كل قطعة وأخرى عند التقطيع للحصول على شرائح ناعمة ونظيفة.","يُحفظ المتبقي مغطى بغلاف بلاستيكي، أو في وعاء مغلق في درجة حرارة الغرفة لمدة 2-3 أيام. ويُحفظ في الثلاجة لمدة 4-5 أيام، أو يُجمّد في وعاء محكم الإغلاق مناسب للفريزر لمدة تصل إلى 3 أشهر. يمكنك تجميده مقطعًا لوجبات إفطار أو وجبات خفيفة سريعة وسهلة، أو تجميد الرغيف كاملًا."],
{"Dry Ingredients":"المكونات الجافة","Wet Ingredients":"المكونات السائلة","Optional":"اختياري"})
R(9708853,"هامبرغر هيلبر نباتي",
"فول الصويا المفروم وصلصة الجبن والمعكرونة تجعل هذا أفضل هامبرغر هيلبر نباتي ستجربه على الإطلاق!",
"4 حصص","حصة واحدة",
["4 أونصات تجعيدات الصويا (soy curls) حوالي نصف كيس من تجعيدات Butler's أو 2.5 كوب","2.5 كوب مرق خضار قليل الصوديوم","1 ملعقة صغيرة كمون","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","3.5 أكواب مرق خضار قليل الصوديوم","1.5 كوب معكرونة كافاتابي أو ماكرونة","½ كوب كاجو نيء","⅔ كوب ماء","2 ملعقة كبيرة خميرة غذائية","1 ملعقة كبيرة خل التفاح","1 ملعقة صغيرة خردل أصفر","1 ملعقة صغيرة صلصة حارة اختياري، لكنها موصى بها","¾ ملعقة صغيرة ملح البحر","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة بابريكا مدخنة"],
["اخلط جميع مكونات \"اللحم\" في وعاء جيدًا. وإذا لم تكن تجعيدات الصويا مغطاة بالكامل، فأضف قليلًا من الماء لتغطيتها. اتركها منقوعة 15 دقيقة، ثم صفّها في مصفاة.","في هذه الأثناء، ضع جميع مكونات صلصة الجبن في الخلاط واخلطها حتى تصبح ناعمة. ضعها جانبًا.","سخّن مقلاة عميقة غير لاصقة على حرارة متوسطة، وعندما تسخن، اعصر الرطوبة الزائدة من تجعيدات الصويا فوق حوض المطبخ وضعها في المقلاة. قلّبها لمدة 3-5 دقائق حتى تحمرّ، مع إضافة رشة ماء أو زيت إذا لزم الأمر لمنع الالتصاق. ثم انقل تجعيدات الصويا إلى محضّر الطعام وشغّله على نبضات متقطعة للحصول على مفروم متجانس وضعه جانبًا.","امسح المقلاة نفسها وأضف 3.5 أكواب من المرق واتركه حتى يغلي غليانًا هادئًا. ثم أضف المعكرونة واتركها على نار هادئة حتى تنضج بقوام \"ألدنتي\" مع التقليب المتكرر. حوالي 10 دقائق.","إذا بقي لديك قليل من المرق الزائد بعد نضج المعكرونة، فلا حاجة إلى تصفيتها. أضف تجعيدات الصويا المفرومة إلى المقلاة وقلّب ليمتص جزءًا من المرق الزائد. ثم اسكب صلصة الجبن فوقها، واخلط جيدًا وقدّم."],
["بما أن تجعيدات الصويا ستُفرم، فلا بأس باستخدام النصف السفلي من الكيس الذي يميل إلى أن يكون مكسّرًا. تأكد من أن تجعيدات الصويا مغطاة تمامًا بالسائل لإعادة ترطيبها. وإذا لزم الأمر، أضف قليلًا من الماء الإضافي إلى الوعاء لتغطيتها. التأكيد على المرق قليل الصوديوم في هذه الوصفة، لمنع الطبق من أن يكون مالحًا جدًا. وإذا لم يكن لديك مرق قليل الملح، فاستخدم خليطًا بنسبة 50/50 من المرق والماء. احرص على ألا تفرط في طهي المعكرونة. في الواقع، من الأفضل أن تكون غير ناضجة قليلًا (أو \"ألدنتي\") لأنها ستواصل التليّن أثناء امتصاصها للمرق الزائد. وإذا كان الهامبرغر هيلبر النباتي سائلًا قليلًا بعد خلط كل شيء، فلا تقلق. فأي سائل زائد سيُمتص بسرعة عندما يبدأ في البرودة. يُستحسن تناول هذا الطبق فورًا، لكن يمكن حفظ المتبقي في الثلاجة في وعاء مغلق لمدة تصل إلى 3 أيام. أعد تسخينه على الموقد مع قليل من المرق أو الحليب النباتي الإضافي لتخفيفه وإعادة ترطيبه."],
{"For the \"Meat\"":"لـ\"اللحم\"","For the Pasta":"للمعكرونة","For the \"Cheese\"":"لـ\"الجبن\""})
R(9709742,"شوربة الجزر والقرنبيط الكريمية بالشبت",
"شوربة جزر وقرنبيط كريمية للغاية، دافئة ومريحة ولذيذة.",
"6 حصص","حصة واحدة",
["1 بصلة صفراء مقطعة مكعبات","1 عود كرفس كبير مقطع مكعبات","4 جزرات كبيرة مقشرة ومقطعة مكعبات (3.5 أكواب)","4 فصوص ثوم مفرومة","1 رأس قرنبيط متوسط مقسّم إلى زهرات (8 أكواب)","1 حبة بطاطا حلوة متوسطة مقشرة ومقطعة مكعبات (4 أكواب)","6 أكواب مرق خضار قليل الصوديوم","3-4 ملاعق كبيرة شبت طازج بالإضافة إلى المزيد للتزيين (أو 2-3 ملاعق صغيرة شبت مجفف)","1 ملعقة صغيرة مريمية مجففة","1 حبة أفوكادو ناضجة مقشرة ومنزوعة النواة","ملح + فلفل حسب الرغبة","كريمة الكاجو","شبت طازج","فلفل أسود أو رقائق الفلفل الأحمر"],
["ضع البصل والكرفس والجزر والثوم في قدر كبير مع 3-4 ملاعق كبيرة من الماء وقلّبها لمدة 5-7 دقائق، حتى تلين.","ثم أضف جميع المكونات المتبقية ما عدا الأفوكادو. اتركها حتى تغلي، ثم خفّف الحرارة واتركها على نار هادئة لمدة 10 دقائق تقريبًا، حتى تلين الخضار عند غرزها بالشوكة.","أطفئ النار، وأضف الأفوكادو، واستخدم الخلاط اليدوي لهرس الشوربة. (أو انقلها بحذر إلى خلاط عادي.) تذوّق الملح والفلفل، وأضف المزيد إذا لزم الأمر.","قدّمها مزيّنة بالشبت الطازج أو كريمة الكاجو أو رقائق الفلفل الأحمر.","اضبط الإنستانت بوت على وضع القلي (Sauté)، وأضف البصل والكرفس والجزر والثوم مع 3-4 ملاعق كبيرة من الماء وقلّبها لمدة 5-7 دقائق، حتى تلين.","ثم أضف جميع المكونات المتبقية ما عدا الأفوكادو. أغلق الغطاء، مع التأكد من أن الصمام في وضع الإغلاق، واضبطه على الضغط العالي لمدة 5 دقائق. (سيستغرق الوصول إلى الضغط حوالي 15 دقيقة.)","عند انتهاء المؤقت، فرّغ الضغط بسرعة عبر صمام البخار وافتح الغطاء عندما يصبح الأمر آمنًا. أضف الأفوكادو واستخدم الخلاط اليدوي لهرس الشوربة. تذوّق الملح والفلفل، وأضف المزيد إذا لزم الأمر، ثم قدّمها."],
["لا تقلق بشأن تقطيع الخضار إلى قطع متساوية الحجم. فبما أنك ستهرس الشوربة، فلا حاجة إلى أحجام متساوية. وهذا سيوفر عليك وقت التحضير.","إذا كنت مستعجلًا، فتجاهل خطوة التقليب واتركها جميعًا على نار هادئة معًا في خطوة واحدة.","استخدم الخلاط اليدوي للهرس لتقليل الفوضى وللسهولة ولتقليل الأطباق التي تحتاج إلى غسل.","إذا لم يكن لديك خلاط يدوي، فكن شديد الحذر عند خلط السوائل الساخنة. لا تملأ الخلاط أكثر من اللازم، واعمل على دفعات لمنع الانسكاب.","تذوّق الملح والفلفل بعد الطهي، وأضف المزيد إذا لزم الأمر. وبحسب المرق الذي تستخدمه، قد ترغب في مزيد من الملح.","هذه الشوربة سميكة القوام. وإذا كنت تفضل قوامًا أخف، فاستخدم كوبًا إضافيًا من المرق أو أضف كوبًا من الحليب النباتي المفضل لديك بعد الهرس.","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام، أو يُجمّد في أوعية محكمة الإغلاق مناسبة للفريزر لمدة تصل إلى 3 أشهر."],
{"Optional Garnishes":"مزيّنات اختيارية","Stovetop Directions":"طريقة التحضير على الموقد","Instant Pot Directions":"طريقة التحضير في الإنستانت بوت"})
R(9712628,"أرز بالفاصوليا في الإنستانت بوت [بدون زيت]",
"طبق أرز بالفاصوليا بسيط في الإنستانت بوت مليء بالنكهة وسهل التحضير.",
"4 حصص","حصة واحدة",
["1 كوب فاصوليا سوداء جافة/غير مطبوخة منقوعة طوال الليل","1 كوب أرز بني","4 أكواب مرق خضار قليل الصوديوم","علبة معجون طماطم سعة 5 أونصات","½ ملعقة صغيرة كمون","½ ملعقة صغيرة بابريكا","½ ملعقة صغيرة مسحوق الفلفل الحار (تشيلي)","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مسحوق البصل","¼ ملعقة صغيرة ملح البحر أو حسب الرغبة","طماطم مقطعة مكعبات، شرائح أفوكادو، كزبرة خضراء، عصير ليمون أخضر، سالسا، غواكامولي، كريمة الكاجو"],
["ضع الفاصوليا المصفاة وجميع المكونات المتبقية في الإنستانت بوت. قلّب لدمجها، ثم أغلق الغطاء مع التأكد من أن الصمام في وضع الإغلاق. اضبطه على الضغط العالي لمدة 30 دقيقة. (سيستغرق بناء الضغط حوالي 10-15 دقيقة قبل بدء العد التنازلي.) اتركه ينفّس تلقائيًا لمدة 10 دقائق، ثم فرّغ أي ضغط متبقٍّ بسرعة.","قدّمه مع الإضافات التي تفضلها."],
["للحصول على فاصوليا أكثر تماسكًا، تجاهل النقع. وللحصول على فاصوليا أطرى تذوب في الفم، انقعها طوال الليل، أو لمدة 6-8 ساعات.","إذا نسيت نقع الفاصوليا، فاستخدم طريقة النقع السريع هذه. ضع الفاصوليا في قدر وغطّها بالماء مع ترك 2-3 بوصات على الأقل من الماء فوق الفاصوليا. ضع الغطاء على القدر، واتركها حتى تغلي على الموقد، ثم ارفعها عن النار، وانقعها لمدة ساعة.","المعلومات الغذائية خاصة بـ ¼ الوصفة ولا تشمل الإضافات الاختيارية. يُحفظ المتبقي في الثلاجة لمدة 3 أيام، وأعد تسخينه مع قليل من الماء أو المرق على الموقد."],
{"Optional Toppings":"إضافات اختيارية"})
R(9713201,"معكرونة بالجبن والبطاطا الحلوة النباتية",
"المعكرونة بالجبن والبطاطا الحلوة طريقة لذيذة لإضافة مزيد من العناصر الغذائية خلسة. غنية بالنكهة وكريمية ومترفة ومخملية بشكل مثالي.",
"6 حصص","حصة واحدة",
["2.5 كوب بطاطا حلوة مقطعة إلى مكعبات بسمك نصف بوصة (حوالي حبتين صغيرتين)","1 بصلة صفراء مقطعة إلى أرباع","2-3 فصوص ثوم غير مقشرة","1 ملعقة صغيرة زيت زيتون يُحذف للحصول على وصفة بدون زيت، انظر الملاحظات**","½ كوب كاجو نيء","¼ كوب خميرة غذائية","1 ملعقة كبيرة بابريكا","1 ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة زعتر مجفف اختياري","1 كوب حليب كاجو غير محلّى أو أي حليب من اختيارك","1 كوب مرق خضار قليل الصوديوم","1 رطل معكرونة ماكرونة أو ما تختاره، خالية من الغلوتين عند الحاجة"],
["سخّن الفرن مسبقًا على 450 درجة فهرنهايت (230° مئوية) وبطّن صينية خبز بورق الزبدة.","ضع البطاطا الحلوة المقطعة مكعبات والبصل المقطع إلى أرباع والثوم (بقشره) على صينية الخبز. رشّ عليها زيت الزيتون وقليلًا من الملح والفلفل واخبزها لمدة 15-20 دقيقة، حتى تلين البطاطا بالشوكة. أخرجها من الفرن.","الآن قشّر الثوم، وضع جميع الخضار المحمصة مع الكاجو والخميرة الغذائية والبابريكا والملح والزعتر والحليب ومرق الخضار في الخلاط واخلطها حتى تصبح ناعمة.","في هذه الأثناء، اغلِ قدرًا كبيرًا من الماء المملح واطهُ المعكرونة وفق تعليمات العبوة للحصول على معكرونة \"ألدنتي\". صفّها وأعدها إلى القدر. اسكب الصلصة فوق المعكرونة واخلط جيدًا.","اختياري: اضبط الفرن على وضع الشواء (برويل) وانقل المعكرونة والصلصة إلى طبق آمن للفرن. ضعه على الرف العلوي لمدة 2-3 دقائق حتى يصبح الوجه ذهبيًا ومقرمشًا، أو حسب درجة \"النضج\" المطلوبة. تفقده كثيرًا حتى لا يحترق."],
["ستتكاثف الصلصة عند تبريدها، لذا إذا كنت تحضّر مسبقًا، فستحتاج إلى إضافة مزيد من المرق أو الحليب عند التقديم. إذا لم يكن لديك خلاط عالي السرعة، فانقع الكاجو في ماء مغلي ساخن لمدة 30 دقيقة تقريبًا أولًا لتليينه. ثم صفّه واستخدمه وفق الإرشادات. للحصول على وصفة خالية من المكسرات: استبدل الكاجو النيء ببذور عباد الشمس، وحليب الكاجو بحليب الصويا أو الشوفان أو أي حليب تحبه. نكهة بذور عباد الشمس أقل اعتدالًا قليلًا مقارنة بالكاجو، لكنها بالتأكيد ليست طاغية. خاصةً عند الأخذ في الاعتبار جميع النكهات والتوابل الأخرى في هذا الطبق. وكميزة إضافية، بذور عباد الشمس مناسبة للميزانية وأقل في الدهون أيضًا! **للحصول على وصفة بدون زيت: احذف الزيت المستخدم لتحميص الخضار. بدلًا من ذلك، يمكنك رش الخضار أو سكب الماء أو المرق عليها لمنعها من الاحتراق. راقبها بعناية. للحصول على وصفة خالية من \"النوتش\" (الخميرة الغذائية): إذا لم يكن لديك خميرة غذائية، أو لا تستطيع العثور عليها، أو لا تريد استخدامها، فيمكنك استبدالها بـ 1-2 ملعقة كبيرة من معجون الميسو أو صلصة الصويا، لكن احذف ملعقة الملح الصغيرة من الصلصة. ضع في اعتبارك أن هذا الاستبدال سيمنحك نكهة أومامي لطيفة، لكن ليس نكهة الجبن التي توفرها الخميرة الغذائية. لمزيد من القرمشة: إذا كنت ستخبز المعكرونة بالجبن اختياريًا، فيمكنك أيضًا إضافة نصف كوب من فتات خبز البانكو فوقها قبل الشواء. سيضيف ذلك مزيدًا من النكهة ومزيدًا من القرمشة إلى الطبقة العلوية."])
R(9715958,"فاهيتا الحمص",
"أضف النكهة إلى عشائك مع فاهيتا الحمص السهلة هذه على صينية الخبز!",
"8 فاهيتا","حصة واحدة",
["علبة حمص سعة 18 أونصة (مصفاة + مغسولة (حوالي 2 كوب))","1 بصلة حمراء (مقطعة شرائح)","3 حبات فلفل رومي (مقطعة شرائح (استخدمت 1 أحمر و1 أخضر و1 برتقالي))","⅓ كوب مرق خضار","1 ملعقة كبيرة مسحوق الفلفل الحار (تشيلي)","1 ملعقة صغيرة كمون","1 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة بابريكا مدخنة","ملح + فلفل (حسب الرغبة)","8 رقائق تورتيلا ذرة ((استخدمت مقاس 6 بوصات))","أفوكادو","غواكامولي","كريمة الكاجو","كزبرة خضراء"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (218° مئوية) بوضع التحميص بالهواء الساخن (الحمل الحراري) وبطّن صينية خبز كبيرة بورق الزبدة. (إذا لم يكن لديك فرن بالهواء الساخن، فاستخدم وضع التحميص أو الخبز العادي وامنحه بضع دقائق إضافية للنضج.)","قطّع الخضار ورتّبها مع الحمص في طبقة واحدة على صينية الخبز.","اخلط جميع مكونات التتبيلة في وعاء صغير. ثم رشّها بالتساوي على الحمص والخضار.","اخبز الخضار لمدة 10-12 دقيقة. ثم اشوِها اختياريًا بوضع الشواء (برويل) لمدة 1-3 دقائق إضافية لتحمرّ الخضار.","قدّمها مع رقائق تورتيلا الذرة وأي إضافات أخرى تحبها."],[])
R(9716519,"كرات خبز الزنجبيل الصحية",
"تخيّل سحر الأعياد الدافئ في لقمة واحدة مع كرات خبز الزنجبيل الرائعة هذه!",
"14 كرة","حصة واحدة",
["1 كوب شوفان مجروش (خالٍ من الغلوتين إن رغبت)","¼ كوب زبدة اللوز","3 ملاعق كبيرة شراب القيقب","1 ملعقة صغيرة خلاصة فانيليا طبيعية","½ ملعقة صغيرة قرفة","¼ ملعقة صغيرة زنجبيل مطحون","⅛ ملعقة صغيرة جوزة الطيب المطحونة","⅛ ملعقة صغيرة قرنفل مطحون","¼ كوب جوز هند مجفف مبشور (للتغليف)"],
["بطّن طبقًا كبيرًا أو صينية خبز بورق الزبدة وضعه جانبًا.","ثم ضع كل شيء ما عدا جوز الهند الاختياري في محضّر الطعام. شغّله على نبضات متقطعة حتى تمتزج المكونات ويصبح الخليط لزجًا بما يكفي لتشكيله على هيئة كرات.","استخدم مغرفة كوكيز صغيرة أو ملعقة كبيرة لاغتراف الخليط، ثم شكّله على هيئة كرة، وضع كل كرة على صينيتك. يجب أن تحصل على حوالي 14 كرة، كل منها ملعقة كبيرة واحدة من الخليط.","اختياري: لفّ بعض الكرات أو كلها في جوز الهند.","ضعها في الثلاجة لمدة ساعة أو أكثر لتتصلب كرات خبز الزنجبيل."],[])
R(9717126,"بانكيك زبدة الفول السوداني النباتي مع كراميل زبدة الفول السوداني",
"بانكيك زبدة الفول السوداني النباتي الشهي مع كراميل زبدة الفول السوداني (PB) هو ما تُصنع منه الأحلام.",
"10 قطع بانكيك","قطعة بانكيك واحدة",
["1 كوب حليب صويا","1 ملعقة صغيرة خل التفاح أو عصير الليمون","1 كوب شوفان مجروش أو شوفان مقطع سريع الطهي","3 ملاعق كبيرة بذور الشيا","2 ملعقة صغيرة بيكنج باودر","⅓ كوب زبدة الفول السوداني الناعمة","2 ملعقة كبيرة صلصة التفاح غير المحلاة","1 كوب تمر منزوع النوى","½ كوب حليب صويا أو أي حليب نباتي من اختيارك","2 ملعقة كبيرة زبدة الفول السوداني الناعمة","½ ملعقة صغيرة قرفة","4-6 ملاعق كبيرة ماء لتخفيف الكراميل إلى القوام المطلوب"],
["ضع حليب الصويا وخل التفاح في وعاء متوسط وضعه جانبًا لمدة 5 دقائق ليتكاثف ويتخثر.","سخّن صينية طهي (جريدل) غير لاصقة على حرارة متوسطة.","في هذه الأثناء، ضع الشوفان وبذور الشيا في الخلاط واخلطها حتى تشبه قوام الدقيق. (لا تقلق إذا بقيت بعض القطع الأخشن.) انقل الخليط إلى وعاء خلط كبير مع البيكنج باودر واخفقها لدمجها.","أضف زبدة الفول السوداني وصلصة التفاح إلى وعاء الحليب المتخثر واخلط جيدًا. ثم اسكب المكونات السائلة في وعاء المكونات الجافة واخلط حتى تمتزج، دون الإفراط في الخلط. بعض الكتل لا بأس بها إطلاقًا.","اغرف العجين على الجريدل الساخن، مع جعل قطر البانكيك حوالي 3-4 بوصات. يمكنك الضغط على البانكيك برفق لمساعدته على الانتشار قليلًا إذا لزم الأمر. (يجب ألا يكون العجين سائلًا جدًا.) لا تفرده كثيرًا لأن طعم هذا البانكيك يكون أفضل عندما يكون سميكًا وهشًا.","اطهُه لمدة 4-5 دقائق حتى يصبح ذهبي اللون ثم اقلبه، واطهُه 3-4 دقائق أخرى حتى ينضج تمامًا.","بينما يُطهى البانكيك، ضع جميع مكونات الكراميل، مع البدء بـ 4 ملاعق كبيرة من الماء، في الخلاط واخلطها حتى تصبح ناعمة. أضف مزيدًا من الماء للوصول إلى القوام المطلوب وضعها جانبًا.","قدّم البانكيك مع شرائح الموز والجوز المفروم ورقائق الشوكولاتة و/أو صلصة الكراميل المنزلية."],
["تأكد من أن الجريدل ساخن قبل طهي البانكيك لمنع الالتصاق ولتجنب دهن المقلاة. يمكنك اختبار ذلك برش رشة ماء على الجريدل لترى ما إذا كانت تتفرقع.","إذا لم يكن لديك خلاط قوي، فانقع التمر لمدة 15-30 دقيقة في ماء مغلي ساخن ثم صفّه، قبل تحضير كراميل زبدة الفول السوداني.","احرص على استخدام بيكنج باودر فعال. فبمجرد فتح البيكنج باودر وتركه في الخزانة لمدة 6 أشهر أو أكثر، قد يبدأ في فقدان قدرته على الانتفاخ.","يُحفظ البانكيك المتبقي في الثلاجة لمدة 3-4 أيام أو في الفريزر لمدة تصل إلى 3 أشهر. أعد تسخينه في محمصة الخبز لوجبات إفطار سريعة محضّرة مسبقًا.","يُحفظ الكراميل المتبقي في وعاء مغلق في الثلاجة لمدة تصل إلى أسبوع.","المعلومات الغذائية لا تشمل صلصة الكراميل الاختيارية. يحتوي عُشر الصلصة على 65 سعرة حرارية، وهو ما يعادل تقريبًا 2-3 ملاعق كبيرة، بحسب كمية الماء المضافة لتخفيف الصلصة."],
{"For the peanut butter pancakes":"لبانكيك زبدة الفول السوداني","For the peanut butter caramel sauce (optional)":"لصلصة كراميل زبدة الفول السوداني (اختياري)"})
R(9717533,"كرات اللحم النباتية بالعدس [بدون زيت + خالية من الغلوتين]",
"كرات اللحم النباتية بالعدس التي ترضي الجميع غنية بالبروتين ومليئة بالنكهة ولذيذة تمامًا.",
"5 حصص (تنتج 20 كرة لحم)","حصة واحدة",
["1 بصلة صفراء مفرومة ناعمًا","1 جزرة كبيرة مقشرة ومقطعة مكعبات","4 فصوص ثوم مفرومة","2 كوب عدس أخضر مطبوخ حوالي ¾ كوب جاف","2 ملعقة كبيرة معجون طماطم","1 ملعقة صغيرة أوريجانو مجفف","1 ملعقة صغيرة ريحان مجفف","¼ كوب خميرة غذائية","1 ملعقة صغيرة ملح البحر","1 كوب بذور اليقطين","معكرونة من اختيارك","نودلز البطاطا الحلوة أو خضار محوّلة إلى شرائح حلزونية من اختيارك","صلصة الطماطم"],
["سخّن الفرن مسبقًا على 400° فهرنهايت (204° مئوية) وبطّن صينية كبيرة بورق الزبدة.","ضع البصل والجزر والثوم في مقلاة مع ملعقة كبيرة أو ملعقتين من الماء وقلّبها لمدة 5 دقائق تقريبًا، حتى تلين. أضف مزيدًا من الماء عند الحاجة لمنع الالتصاق.","ضع الخضار المطبوخة والعدس المطبوخ ومعجون الطماطم وجميع التوابل في محضّر الطعام واخلطها حتى تمتزج، لكن دون أن تتحول إلى هريس، مع كشط الجوانب عند الحاجة. ثم أضف بذور اليقطين وشغّل المحضّر على نبضات متقطعة بضع مرات لتفتيتها وخلطها لكن دون الإفراط في الخلط. تذوّق الخليط وأضف مزيدًا من التوابل إن رغبت.","شكّل الخليط على هيئة كرات صغيرة (قطرها حوالي 1-1.5 بوصة) وضعها على الصينية المجهزة. يجب أن تحصل على 20 كرة لحم نباتية بالعدس.","اخبزها لمدة 25-30 دقيقة، ثم أخرجها من الفرن واتركها تبرد 3-5 دقائق قبل لمسها.","تمتّع بها كما هي، أو مع المعكرونة وصلصة المارينارا، أو الأرز، أو نودلز البطاطا الحلوة."],
["استخدم العدس الأخضر الجاف المطبوخ للحصول على أفضل قوام. لا تستبدله بالأحمر لأنه يصبح هلاميًا جدًا لهذه الكرات. وللحصول على عمق أكبر في النكهة، اطهُ العدس في مرق الخضار.","احرص على ألا تفرط في طهي العدس وإلا سيصبح طريًا جدًا. اطهُه وفق تعليمات العبوة، لكن قلّل وقت الطهي بمقدار 1-2 دقيقة للحصول على أفضل النتائج. (سينضج أكثر في الفرن لاحقًا.)","لا تفرط في خلط المكونات. فهذا سيجعل الخليط طريًا جدًا، ويصعب تشكيله، ويؤدي إلى قوام أطرى/أكثر هلامية. (وإذا حدث ذلك، فيمكنك وضعه في الثلاجة قليلًا ليتماسك بما يكفي لتشكيله، أو إضافة بعض الشوفان أو فتات الخبز لتقوية القوام.","استخدم يدين مبللتين لتشكيل الكرات. فهذا سيمنعها من الالتصاق بيديك وأصابعك، مما يسهّل تشكيلها.","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام أو يُجمّد في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر. حجم الحصة حوالي 4 كرات لحم نباتية بالعدس."],
{"For serving (optional)":"للتقديم (اختياري)"})
R(9717936,"مايونيز نباتي حار بطريقتين [بدون زيت]",
"مايونيز نباتي كريمي ولاذع وحار، يُحضّر بمكونات صحية وجاهز في وقت قصير.",
"10 حصص (حوالي 1.25 كوب)","حصة واحدة",
["1 كوب كاجو نيء أو بذور يقطين نيئة مقشرة","⅓ كوب + 2 ملعقة كبيرة ماء","2 ملعقة كبيرة عصير ليمون حوالي نصف ليمونة","1 ملعقة كبيرة خل التفاح","1 ملعقة صغيرة مسحوق الثوم أو مسحوق البصل","½-1 ملعقة صغيرة فلفل كايين أو حسب الرغبة","¼ ملعقة صغيرة ملح البحر أو حسب الرغبة","1 ملعقة صغيرة خردل أصفر اختياري، تجاهله لتقليل النكهة اللاذعة"],
["ضع جميع المكونات في خلاط عالي السرعة، مع البدء بـ ⅓ كوب فقط من الماء، واخلطها حتى تصبح ناعمة. ابدأ على سرعة منخفضة وارفعها تدريجيًا حتى لا تتطاير قطع الكاجو السائبة إلى أعلى الخلاط. وبعد أن تصبح ناعمة، أضف بقية الماء (إن رغبت) واخلط لدمجه.","ضعه في الثلاجة لمدة ساعة على الأقل، لأن طعمه يكون أفضل بارد. ثم قدّمه مع الخضار أو البطاطس المقلية أو البيتزا أو السندويشات أو اللفائف أو البرغر. بالهناء والشفاء"],
["المعلومات الغذائية خاصة بعُشر الوصفة، حوالي ملعقتين كبيرتين، باستخدام طريقة الكاجو. وإذا استبدلته ببذور اليقطين، فستكون السعرات الحرارية والدهون أقل بكثير. إذا لم يكن لديك فيتامكس أو خلاط عالي السرعة، فانقع الكاجو في ماء مغلي ساخن لمدة 30 دقيقة ثم صفّه. اكشط الجوانب عند الحاجة للحصول على قوام ناعم وكريمي. ابدأ الخلط بـ ⅓ كوب فقط من الماء المطلوب في البداية. فهذا يساعد على الحصول على قوام أنعم لأن قطع الكاجو يكون أمامها مساحة أقل للطفو. ثم أضف الملعقتين الكبيرتين الإضافيتين واخلط لدمجهما."])
